function tableLiveIndices(d){if(!tableLiveTrace)return null;const xvals=tableAxisValues(d,'x').map(Number),yvals=tableAxisValues(d,'y').map(Number),axisValue=(axis)=>{const q=[axis==='x'?d.xChannel:d.yChannel,axis==='x'?d.xLabel:d.yLabel,axis==='x'?d.xUnits:d.yUnits,axis==='x'?d.x:d.y].join(' ').toLowerCase();if(q.includes('rpm'))return Number(state.rpm);if(q.includes('tps')||q.includes('throttle'))return Number(state.tps);if(q.includes('coolant')||q.includes('clt'))return Number(state.clt);if(q.includes('intake')||q.includes('iat'))return Number(state.iat);if(q.includes('vbatt')||q.includes('battery')||q.includes('volt'))return Number(state.batt);if(q.includes('kpa')||q.includes('load')||q.includes('map')||q.includes('pressure')||q.includes('ve y')||q.includes('veload'))return Number(state.map);return NaN};const xv=axisValue('x'),yv=axisValue('y');if(!Number.isFinite(xv)||!Number.isFinite(yv)||!xvals.some(Number.isFinite)||!yvals.some(Number.isFinite))return null;const near=(arr,v)=>arr.reduce((best,n,i)=>Number.isFinite(n)&&Math.abs(n-v)<best.diff?{i,diff:Math.abs(n-v)}:best,{i:0,diff:Infinity}).i;return{r:near(yvals,yv),c:near(xvals,xv),xv,yv}}
